CREATE TABLE "patients" (
    "id" SERIAL,
    "name" VARCHAR(100),
    PRIMARY KEY ("id")
);

CREATE TABLE "appointments" (
    "id" SERIAL,
    "patient_id" VARCHAR(100),
    "doctor_id" VARCHAR(100),
    "date" DATE,
    PRIMARY KEY ("id")
);

CREATE TABLE "doctors" (
    "id" SERIAL,
    "name" VARCHAR(100),
    PRIMARY KEY ("id")
);

CREATE TABLE "records" (
    "id" SERIAL,
    "patient_id" VARCHAR(100),
    "doctor_id" VARCHAR(100),
    "date" DATE,
    PRIMARY KEY ("id")
);

CREATE TABLE "authentication" (
    "id" SERIAL,
    "username" VARCHAR(100),
